const TEAM={1:'ATL',2:'BUF',3:'CHI',4:'CIN',5:'CLE',6:'DAL',7:'DEN',8:'DET',9:'GB',10:'TEN',11:'IND',12:'KC',13:'LV',14:'LAR',15:'MIA',16:'MIN',17:'NE',18:'NO',19:'NYG',20:'NYJ',21:'PHI',22:'ARI',23:'PIT',24:'LAC',25:'SF',26:'SEA',27:'TB',28:'WAS',29:'CAR',30:'JAC',33:'BAL',34:'HOU'};
const POS={1:'QB',2:'RB',3:'WR',4:'TE',5:'K',16:'D/ST'};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function normalizedLeague(raw,ownerSwid=''){
 if(!Array.isArray(raw.teams)||!raw.teams.length)throw new Error('No teams returned');
 return {name:raw.settings?.name||'ESPN league',week:raw.scoringPeriodId||0,ownedTeamId:ownerSwid?String(raw.teams.find(t=>t.owners?.some(x=>String(x).toUpperCase()===ownerSwid.toUpperCase()))?.id||''):'',teams:raw.teams.map(t=>({id:String(t.id),name:t.name||[t.location,t.nickname].filter(Boolean).join(' ')||t.abbrev||`Team ${t.id}`,players:(t.roster?.entries||[]).filter(e=>![20,21].includes(Number(e.lineupSlotId))).map(e=>{const p=e.playerPoolEntry?.player||{};return{id:String(p.id||''),name:p.fullName||'',team:TEAM[p.proTeamId]||'',position:POS[p.defaultPositionId]||''};}).filter(p=>p.name&&p.team&&p.position)}))};
}
async function leagueAPI(request,env={},fetcher=fetch){
 if(request.method!=='POST')return json({error:'Use POST.'},405);
 const origin=request.headers.get('Origin');if(origin&&origin!==new URL(request.url).origin)return json({error:'Invalid request origin.'},403);
 let data;try{if(Number(request.headers.get('Content-Length')||0)>1024)return json({error:'Request too large.'},413);const text=await request.text();if(text.length>1024)return json({error:'Request too large.'},413);data=JSON.parse(text);}catch{return json({error:'Enter a valid league ID.'},400);}
 const id=String(data.leagueId||'');const now=new Date();const season=now.getUTCFullYear()-(now.getUTCMonth()<5?1:0);const year=Number(data.season||season);
 if(!/^\d{1,12}$/.test(id)||!Number.isInteger(year)||year<2018||year>season+1)return json({error:'Enter a numeric ESPN league ID.'},400);
 const owner=request.headers.get('oai-authenticated-user-id')===env.ESPN_OWNER_ID;
 const useSaved=!!(owner&&id===env.ESPN_LEAGUE_ID&&env.ESPN_SWID&&env.ESPN_S2);
 const headers={Accept:'application/json'};if(useSaved)headers.Cookie=`SWID=${env.ESPN_SWID}; espn_s2=${env.ESPN_S2}`;
 try{const response=await fetcher(`https://lm-api-reads.fantasy.espn.com/apis/v3/games/ffl/seasons/${year}/segments/0/leagues/${id}?view=mRoster&view=mTeam&view=mSettings`,{headers,redirect:'error',signal:AbortSignal.timeout(12000)});
 if([401,403,404].includes(response.status))return json({error:useSaved?'ESPN could not open this league with the saved access. The login may have expired, or the league/season is unavailable.':'This league is private or unavailable. League ID alone works for public leagues; private leagues need an ESPN connection.'},response.status===404?404:401);
 if(!response.ok)return json({error:'ESPN is temporarily unavailable. Please try again.'},502);
 const raw=await response.json();if(!raw.teams?.length)return json({error:useSaved?'ESPN did not return your roster. Your saved login may need refreshing.':'ESPN did not return this league. Check the ID and league visibility.'},422);
 return json({...normalizedLeague(raw,useSaved?env.ESPN_SWID:''),leagueId:id,season:year});
 }catch{return json({error:'Could not reach ESPN. Try again shortly.'},502);}
}

const assets={"/adapters.js":{"type":"text/javascript","body":"// ESPN adapters keep provider data separate from directing policy.\nconst POSITIONS = {1:'QB',2:'RB',3:'WR',4:'TE',5:'K',16:'D/ST'};\nconst INACTIVE_SLOTS = new Set([20,21]); // ESPN bench and IR\nconst id = value => value == null ? '' : String(value);\nexport function normalizeLeague(raw) {\n  if (!Array.isArray(raw?.teams) || !raw.teams.length) throw new Error('ESPN returned no teams. Check league, season, and login.');\n  return {week:Number(raw.scoringPeriodId || raw.status?.currentMatchupPeriod || 0), teams:raw.teams.map(t => ({\n    id:id(t.id), name:t.name || [t.location,t.nickname].filter(Boolean).join(' ') || t.abbrev || `Team ${t.id}`,\n    players:(t.roster?.entries || []).map(e => {\n      const p=e.playerPoolEntry?.player || e.player || {};\n      return {id:id(p.id), name:p.fullName || 'Unknown player', teamId:id(p.proTeamId), position:POSITIONS[p.defaultPositionId] || 'OTHER', starter:!INACTIVE_SLOTS.has(Number(e.lineupSlotId)), slot:Number(e.lineupSlotId), injury:p.injuryStatus || ''};\n    }).filter(p=>p.id)\n  }))};\n}\nexport function normalizeScoreboard(raw, fetchedAt=Date.now()) {\n  if (!Array.isArray(raw?.events)) throw new Error('Unexpected NFL scoreboard format.');\n  return raw.events.map(e => {\n    const c=e.competitions?.[0] || {}, s=c.situation || {}, status=c.status || e.status || {};\n    const teams=(c.competitors || []).map(t=>({id:id(t.team?.id || t.id), abbreviation:t.team?.abbreviation || '?', score:String(t.score ?? '0'), homeAway:t.homeAway})).sort((a,b)=>(a.homeAway==='away'?0:1)-(b.homeAway==='away'?0:1));\n    const rawPossession=id(s.possession?.id ?? s.possession);\n    // Never infer possession from lastPlay.team: that can be the scoring team,\n    // the team before a turnover, or an arbitrary timeout participant.\n    const possession=teams.some(t=>t.id===rawPossession) ? rawPossession : '';\n    return {id:id(e.id), name:e.shortName || e.name || 'NFL game', teams, date:e.date,\n      state:status.type?.completed ? 'post' : status.type?.state || 'pre', statusName:status.type?.name || '',\n      detail:status.type?.shortDetail || status.type?.detail || 'Scheduled', period:Number(status.period || 0),\n      clock:status.displayClock || '', possession, redZone:s.isRedZone===true,\n      down:Number(s.down || 0), downDistance:s.downDistanceText || '',\n      lastPlay:s.lastPlay?.text || '', lastPlayId:id(s.lastPlay?.id), playType:s.lastPlay?.type?.text || '', playWallclock:Date.parse(s.lastPlay?.wallclock) || null, phase:playPhase(s.lastPlay), yardsToGoal:scoringDistance(s,teams,possession), fetchedAt};\n  }).filter(g=>g.id && g.teams.length===2);\n}\nexport function scoringDistance(situation, teams, possession) {\n  // ESPN's raw yardLine has an orientation-dependent origin. Do not guess it.\n  if (!possession) return null;\n  const explicit=situation.yardsToEndzone;\n  if (explicit!==null && explicit!==undefined && explicit!=='' && Number.isFinite(Number(explicit)) && Number(explicit)>=0 && Number(explicit)<=100) return Number(explicit);\n  const text=String(situation.possessionText || situation.downDistanceText || '').toUpperCase();\n  const match=text.match(/(?:^|\\bAT\\s+)([A-Z]{2,4})\\s+(\\d{1,2})(?:\\b|$)/);\n  if (!match || Number(match[2])>50) return null;\n  const alias=x=>({WSH:'WAS',JAX:'JAC',LA:'LAR'})[x] || x;\n  const side=teams.find(t=>alias(t.abbreviation)===alias(match[1]));\n  if (!side) return null;\n  return side.id===possession ? 100-Number(match[2]) : Number(match[2]);\n}\n\nexport function playPhase(play={}) {\n  if(/no play|reversed|overturned/i.test(play.text || ''))return 'scrimmage';\n  if(play.scoringPlay || /touchdown|field goal good|extra point|two.point (pass|rush|conversion)/i.test(play.type?.text || '') || /\\bTOUCHDOWN\\b/.test(play.text || ''))return 'between-drives';\n  return 'scrimmage';\n}\n"},"/app.js":{"type":"text/javascript","body":"import {SOURCES,scenarios} from './replays.js';\nimport {normalizeScoreboard} from './adapters.js';\nimport {normalizeHighlights,playable} from './highlights.js';\nimport {chooseGame,involved,parseRoster,safeVideo,gameKey} from './director.js';\nconst $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst SAMPLE=[{name:'A.J. Brown',team:'PHI',position:'WR'},{name:'Jonathan Taylor',team:'IND',position:'RB'}];\nconst BASE='https://site.api.espn.com/apis/site/v2/sports/football/nfl/';\nlet saved={roster:SAMPLE,teamName:'Sample roster',streams:{},leagueId:'',teamId:'',season:2026};\ntry{const old=JSON.parse(localStorage.getItem('fd-simple-v2')||'null');if(old){saved={...saved,...old};saved.roster=parseRoster(old.roster.map(p=>`${p.name}, ${p.team}, ${p.position}`).join('\\n'));saved.streams=Object.fromEntries(Object.entries(old.streams||{}).map(([key,v])=>[key,safeVideo(v)]));}}catch{}\nlet state={mode:'replay',step:0,running:false,auto:true,games:[],currentId:'replay-phi',loaded:'',playerStarted:false,clip:null,clipManual:false,clips:[],played:new Set(),quietAt:null,lastClip:-Infinity,changedAt:0,lastFeed:0,feedError:'',generation:0,pendingLeague:null,failedURL:'',side:'games'};\nlet testTimer,feedTimer,clipTimer,clipTimeout,toastTimer,feedController,clipController;\nstate.games=scenarios(0);\nfunction persist(){try{localStorage.setItem('fd-simple-v2',JSON.stringify(saved));}catch{notice('Settings are applied for this visit; browser storage is unavailable.');}}\nfunction notice(text){$('notice').textContent=text;$('notice').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('notice').hidden=true,6000);}\nfunction activeGame(){return state.games.find(g=>g.id===state.currentId);}\nfunction showSide(name){state.side=name;for(const n of ['games','roster','clips']){$(n+'Panel').hidden=n!==name;$(n+'Tab').setAttribute('aria-selected',n===name);} }\nfor(const name of ['games','roster','clips']){$(name+'Tab').onclick=()=>showSide(name);$(name+'Tab').onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=['games','roster','clips'];const next=tabs[(tabs.indexOf(name)+(e.key==='ArrowRight'?1:2))%3];showSide(next);$(next+'Tab').focus();};}\n$('connectionButton').onclick=()=>{$('connectBar').hidden=!$('connectBar').hidden;if(!$('connectBar').hidden)$('leagueId').focus();};\n$('leagueId').value=saved.leagueId;if(saved.teamId)$('connectBar').hidden=true;\nasync function importLeague(refresh=false){const leagueId=refresh?saved.leagueId:$('leagueId').value.trim();if(!/^\\d{1,12}$/.test(leagueId)){$('importStatus').textContent='Enter the numeric league ID from ESPN.';return;}\n $('importButton').disabled=true;$('refreshRoster').disabled=true;$('importButton').textContent='Importing…';$('importStatus').textContent='Getting your teams from ESPN…';$('teamPicker').hidden=true;\n try{const response=await fetch('/api/league',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({leagueId}),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not import this league.');state.pendingLeague=data;\n const selected=data.teams.find(t=>t.id===(leagueId===saved.leagueId?saved.teamId:null))||data.teams.find(t=>t.id===data.ownedTeamId)||(data.teams.length===1?data.teams[0]:null);\n if(selected){applyTeam(data,selected);return;}\n $('teamSelect').innerHTML=data.teams.map(t=>`<option value=\"${escape(t.id)}\">${escape(t.name)}</option>`).join('');$('teamPicker').hidden=false;$('importStatus').textContent=`${data.teams.length} teams found. Choose yours once.`;\n }catch(e){$('connectBar').hidden=false;$('importStatus').textContent=e.name==='TimeoutError'?'ESPN took too long. Please try again.':e.message;}\n finally{$('importButton').disabled=false;$('refreshRoster').disabled=false;$('importButton').textContent='Import roster';}}\n$('leagueForm').onsubmit=e=>{e.preventDefault();importLeague();};$('refreshRoster').onclick=()=>importLeague(true);\n$('useTeam').onclick=()=>{const data=state.pendingLeague;const team=data?.teams.find(t=>t.id===$('teamSelect').value);if(team)applyTeam(data,team);};\nfunction applyTeam(data,team){saved={...saved,roster:team.players,teamName:team.name,leagueId:data.leagueId,season:data.season,teamId:team.id};persist();$('connectBar').hidden=true;$('teamPicker').hidden=true;$('importStatus').textContent=`${team.players.length} starters imported.`;state.pendingLeague=null;direct();render();showSide('roster');notice(`${team.name}: ${team.players.length} starters imported.`);}\nfunction unload(video){video.pause();video.removeAttribute('src');video.load();video.hidden=true;}\nfunction clearGame(){if($('gameFrame').hasAttribute('src'))$('gameFrame').removeAttribute('src');$('gameFrame').hidden=true;if($('gameVideo').hasAttribute('src'))unload($('gameVideo'));state.loaded='';}\nasync function startVideo(video){video.muted=true;try{await video.play();$('playVideo').hidden=true;}catch{$('playVideo').hidden=false;}}\nfunction sourceFor(g){return state.mode==='replay'?g?.embed:g&&saved.streams[gameKey(g)];}\nfunction loadPlayer(){\n const g=activeGame(),url=sourceFor(g);$('returnLive').hidden=!state.clip;\n if(state.clip){$('playerEmpty').hidden=true;return;}\n $('clipVideo').hidden=true;\n if(!state.playerStarted||!url){clearGame();$('playerEmpty').hidden=false;$('playerEmpty').querySelector('h1').textContent=state.mode==='replay'?'Ready when you are.':'Connect a game stream.';$('playerEmpty').querySelector('p').textContent=state.mode==='replay'?'Two full-game replays are ready to test.':'Choose Settings to add a compatible video URL.';$('loadReplay').textContent=state.mode==='replay'?'Load replay':'Stream settings';return;}\n if(state.failedURL===url){$('playerEmpty').hidden=false;$('playerEmpty').querySelector('h1').textContent='This video is unavailable.';$('playerEmpty').querySelector('p').textContent='Check your stream URL in Settings.';$('loadReplay').textContent='Stream settings';return;}\n $('playerEmpty').hidden=true;if(state.loaded===url)return;clearGame();state.loaded=url;$('playVideo').hidden=true;\n if(state.mode==='replay'){$('gameFrame').src=url;$('gameFrame').hidden=false;}\n else {if(/\\.m3u8(?:\\?|$)/i.test(url)&&!$('gameVideo').canPlayType('application/vnd.apple.mpegurl')){state.failedURL=url;notice('This HLS source needs a browser with native HLS support, such as Safari.');loadPlayer();return;}$('gameVideo').src=url;$('gameVideo').hidden=false;startVideo($('gameVideo'));}\n}\n$('loadReplay').onclick=()=>{if(state.mode==='replay'&&!state.failedURL){state.playerStarted=true;loadPlayer();}else openSettings();};\n$('gameVideo').onerror=()=>{if(state.loaded&&state.mode==='live'){state.failedURL=state.loaded;loadPlayer();}};\n$('playVideo').onclick=()=>startVideo(state.clip?$('clipVideo'):$('gameVideo'));\nfunction finishClip(){clearTimeout(clipTimeout);state.clip=null;unload($('clipVideo'));$('playVideo').hidden=true;loadPlayer();}\n$('returnLive').onclick=()=>{finishClip();render();};$('clipVideo').onended=()=>{finishClip();render();};$('clipVideo').onerror=()=>{if(state.clip){notice('This highlight is unavailable. Returning to the game.');finishClip();render();}};\nfunction playClip(clip,manual=false){if(!playable(clip)){notice('This highlight is available at the ESPN link.');return;}finishClip();clearGame();state.clip=clip;state.clipManual=manual;state.played.add(clip.id);state.lastClip=Date.now();$('clipVideo').src=clip.mediaUrl;$('clipVideo').hidden=false;startVideo($('clipVideo'));clipTimeout=setTimeout(()=>{if(state.clip){finishClip();render();}},Math.min(120000,Math.max(20000,(clip.duration+15)*1000)));render();}\nfunction stale(){return !state.lastFeed||Date.now()-state.lastFeed>(state.games.some(g=>g.state==='in')?20000:90000);}\nfunction direct(){if(!state.auto)return;if(state.mode==='live'&&stale())return;\n const pick=chooseGame(state.games,saved.roster,state.currentId,state.changedAt,Date.now());\n if(pick){if(state.currentId!==pick.game.id){state.currentId=pick.game.id;state.changedAt=Date.now();}if(pick.urgent&&state.clip&&!state.clipManual)finishClip();}\n if(!pick||!pick.urgent){if(state.quietAt===null)state.quietAt=Date.now();}else state.quietAt=null;\n if($('autoClips').checked&&state.playerStarted&&!state.clip&&(state.mode==='live'||state.running)&&state.quietAt!==null&&Date.now()-state.quietAt>2000&&Date.now()-state.lastClip>(state.mode==='replay'?20000:120000)){\n const clip=state.clips.find(c=>!state.played.has(c.id)&&playable(c)&&c.duration>0&&c.duration<=90);if(clip)playClip(clip);\n }}\nfunction render(){const g=activeGame(),test=state.mode==='replay',players=g?involved(g,saved.roster):[];\n $('replayMode').setAttribute('aria-pressed',test);$('liveMode').setAttribute('aria-pressed',!test);$('autoDirector').checked=state.auto;$('testBar').hidden=!test;\n $('modeCaption').textContent=state.clip?'HIGHLIGHT':test?'REPLAY TEST':g?.state==='in'?'LIVE GAME':'SELECTED GAME';\n $('gameTitle').textContent=state.clip?state.clip.title:g?(test?g.name:g.name.replace(' @ ',' at ')):'No game selected';\n $('reason').textContent=state.clip?'The game returns when this highlight ends.':!g?'Waiting for the NFL slate.':!state.auto?'Pinned to this game. Turn Auto director on to follow the action.':players.length?`${players.map(p=>p.name).join(', ')} · ${players[0].position==='D/ST'?'defense':'offense'} has possession.`:g.statusName==='STATUS_HALFTIME'?'Quiet moment. A highlight can play here.':g.state!=='in'?g.detail:`Roster quiet · ${g.yardsToGoal??'unknown'} yards to the end zone.`;\n $('connectionButton').textContent=saved.teamId?saved.teamName:'Connect roster';$('connectionButton').title=saved.teamName;\n $('teamName').textContent=saved.teamName;$('refreshRoster').hidden=!saved.teamId;$('rosterNote').textContent=saved.teamId?`${saved.roster.length} starters · ESPN league ${saved.leagueId}`:saved.teamName==='Sample roster'?'Import your team above to replace these players.':'Your manually entered starters.';\n $('rosterList').innerHTML=saved.roster.map(p=>`<div class=\"roster-item ${players.some(a=>a.name===p.name)?'active':''}\"><span class=\"position\">${escape(p.position)}</span><div><strong>${escape(p.name)}</strong><small>${escape(p.team)}</small></div></div>`).join('')||'<p class=\"empty-list\">No starters selected. Auto director will follow scoring threats.</p>';\n $('gamesHeading').textContent=test?'Test games':'NFL games';$('feedStatus').textContent=test?'Week 7 replays':state.feedError?'Feed unavailable':!state.lastFeed?'Loading…':stale()?'Stale data':'ESPN';\n $('gameList').innerHTML=state.games.map(game=>`<button class=\"game\" data-game=\"${escape(game.id)}\" aria-pressed=\"${state.currentId===game.id}\"><strong>${escape(test?game.name:game.name)}</strong><span class=\"game-meta\">${test?'Full-game replay · Week 7':escape(game.detail)+' · '+game.teams.map(t=>escape(t.score)).join(' – ')}</span><span class=\"game-state\">${game.id===state.currentId?'Selected':test?'Replay ready':game.redZone?'Red zone':game.state==='in'?'In progress':'Scheduled'}</span></button>`).join('')||'<p class=\"empty-list\">No games available. Replay test works any day.</p>';\n $('clipList').innerHTML=state.clips.slice(0,6).map(c=>`<div class=\"clip\"><button data-clip=\"${escape(c.id)}\">${playable(c)?'▶ ':''}${escape(c.title)}${state.played.has(c.id)?' · Played':''}</button><a href=\"${escape(c.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">Watch on ESPN ↗</a></div>`).join('')||'<p class=\"empty-list\">Loading published highlights. Only playable clips enter the automatic queue.</p>';\n $('testStep').textContent=`${state.step+1} of 5`;$('startTest').textContent=state.running?'Pause test':'Start test';\n $('playerNote').hidden=!test;$('sourceLink').hidden=!test||!g;$('playbackNote').hidden=!test;if(test&&g)$('sourceLink').href=g.page;\n loadPlayer();\n}\n$('gameList').onclick=e=>{const b=e.target.closest('[data-game]');if(!b)return;state.currentId=b.dataset.game;state.auto=false;state.playerStarted=true;finishClip();render();};\n$('clipList').onclick=e=>{const b=e.target.closest('[data-clip]');if(b){const c=state.clips.find(x=>x.id===b.dataset.clip);if(c)playClip(c,true);}};\n$('autoDirector').onchange=e=>{state.auto=e.target.checked;if(state.auto){finishClip();direct();}render();};\n$('autoClips').onchange=e=>{if(!e.target.checked&&state.clip&&!state.clipManual){finishClip();render();}};\nfunction stepTest(next){state.step=next;state.games=scenarios(next);state.quietAt=null;direct();render();}\nfunction scheduleTest(){clearTimeout(testTimer);if(state.running)testTimer=setTimeout(()=>{stepTest((state.step+1)%5);scheduleTest();},18000);}\n$('startTest').onclick=()=>{state.running=!state.running;state.playerStarted=true;if(state.running){state.auto=true;direct();}scheduleTest();render();};\n$('nextTest').onclick=()=>{state.playerStarted=true;state.auto=true;stepTest((state.step+1)%5);scheduleTest();};\n$('restartTest').onclick=()=>{state.auto=true;state.played.clear();state.lastClip=-Infinity;finishClip();stepTest(0);scheduleTest();};\nasync function json(path,signal){const response=await fetch(BASE+path,{signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(!response.ok)throw new Error('ESPN unavailable');return response.json();}\nasync function livePoll(generation){if(generation!==state.generation||state.mode!=='live')return;feedController=new AbortController();const timeout=setTimeout(()=>feedController.abort(),8000);try{const games=normalizeScoreboard(await json('scoreboard',feedController.signal));if(generation!==state.generation)return;state.games=games;state.lastFeed=Date.now();state.feedError='';if(!activeGame())state.currentId=games.find(g=>g.state==='in')?.id||games[0]?.id;direct();render();}catch{if(generation===state.generation){state.feedError='Unavailable';$('feedStatus').textContent='Feed unavailable · auto held';}}finally{clearTimeout(timeout);if(generation===state.generation)feedTimer=setTimeout(()=>livePoll(generation),!document.hidden&&state.games.some(g=>g.state==='in')?5000:30000);}}\nasync function fetchClips(generation){clipController=new AbortController();const timeout=setTimeout(()=>clipController.abort(),15000);try{\n let games=state.games;if(state.mode==='replay'){games=normalizeScoreboard(await json('scoreboard?dates=20261025-20261026',clipController.signal)).filter(g=>g.teams.some(t=>['PHI','IND'].includes(t.abbreviation)));}\n const eligible=games.filter(g=>g.state==='in'||g.state==='post');\n const incoming=[];for(const g of eligible.slice(0,2)){const raw=await json('summary?event='+encodeURIComponent(g.id),clipController.signal);incoming.push(...normalizeHighlights(raw,g).filter(c=>c.kind==='clip'));}\n if(generation!==state.generation)return;state.clips=[...new Map([...state.clips,...incoming].map(c=>[c.id,c])).values()].slice(0,24);render();if(!state.clips.length)$('clipList').innerHTML='<p class=\"empty-list\">No published highlights are available for these games yet.</p>';\n }catch{if(generation===state.generation&&!state.clips.length)$('clipList').innerHTML='<p class=\"empty-list\">Highlights are temporarily unavailable. The game replays are still ready.</p>';}\n finally{clearTimeout(timeout);if(generation===state.generation&&state.mode==='live')clipTimer=setTimeout(()=>fetchClips(generation),30000);}}\nfunction stopNetwork(){clearTimeout(feedTimer);clearTimeout(clipTimer);feedController?.abort();clipController?.abort();}\nfunction mode(name){if(state.mode===name)return;stopNetwork();clearTimeout(testTimer);finishClip();clearGame();state.generation++;state.mode=name;state.running=false;state.playerStarted=false;state.auto=true;state.step=0;state.games=name==='replay'?scenarios(0):[];state.currentId=state.games[0]?.id;state.lastFeed=0;state.clips=[];state.played.clear();state.quietAt=null;state.failedURL='';render();if(name==='live')livePoll(state.generation);fetchClips(state.generation);}\n$('replayMode').onclick=()=>mode('replay');$('liveMode').onclick=()=>mode('live');\nfunction openSettings(){const games=state.mode==='live'&&state.games.length?state.games:SOURCES;$('streamInputs').innerHTML=games.map(g=>`<div class=\"stream-row\"><label for=\"stream-${escape(g.id)}\">${escape(g.name)}</label><input id=\"stream-${escape(g.id)}\" data-key=\"${escape(gameKey(g))}\" type=\"url\" value=\"${escape(saved.streams[gameKey(g)]||'')}\" placeholder=\"https://…/stream.m3u8\"></div>`).join('');$('manualRoster').value=saved.roster.map(p=>`${p.name}, ${p.team}, ${p.position}`).join('\\n');$('settingsError').textContent='';$('settingsDialog').showModal();}\n$('settingsButton').onclick=openSettings;$('closeSettings').onclick=()=>$('settingsDialog').close();\n$('settingsForm').onsubmit=e=>{e.preventDefault();try{const roster=parseRoster($('manualRoster').value),streams={...saved.streams};for(const field of $('streamInputs').querySelectorAll('input'))streams[field.dataset.key]=safeVideo(field.value.trim());const changed=JSON.stringify(roster)!==JSON.stringify(saved.roster.map(({name,team,position})=>({name,team,position})));saved={...saved,roster,streams,...(changed?{teamName:'My roster',teamId:'',leagueId:''}:{})};persist();state.failedURL='';state.loaded='';if(state.mode==='live')state.playerStarted=true;$('settingsDialog').close();direct();render();notice('Settings saved.');}catch(err){$('settingsError').textContent=err.message;}};\nsetInterval(()=>{if(document.hidden)return;const before=state.currentId,clip=state.clip?.id;if(state.mode==='live'||state.running)direct();if(before!==state.currentId||clip!==state.clip?.id)render();if(state.mode==='live'&&stale())$('feedStatus').textContent=state.lastFeed?'Stale data · auto held':'Connecting…';},1000);\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(testTimer);else scheduleTest();});\nwindow.addEventListener('pagehide',()=>{stopNetwork();clearTimeout(testTimer);clearTimeout(clipTimeout);clearGame();$('clipVideo').pause();});\nwindow.addEventListener('pageshow',e=>{if(e.persisted){state.generation++;if(state.mode==='live')livePoll(state.generation);fetchClips(state.generation);loadPlayer();scheduleTest();}});\nrender();fetchClips(state.generation);\n"},"/director.js":{"type":"text/javascript","body":"export const SAMPLE_ROSTER = [\n {name:'Caleb Williams',team:'CHI',position:'QB'},\n {name:'A.J. Brown',team:'PHI',position:'WR'},\n {name:'Jonathan Taylor',team:'IND',position:'RB'}\n];\nexport const TEAMS = 'ARI ATL BAL BUF CAR CHI CIN CLE DAL DEN DET GB HOU IND JAC KC LAC LAR LV MIA MIN NE NO NYG NYJ PHI PIT SEA SF TB TEN WAS'.split(' ');\nexport const alias = t => ({WSH:'WAS',JAX:'JAC',LA:'LAR'}[t] || t);\nexport function involved(game, roster) {\n if(game.state!=='in'||!game.possession||game.phase==='between-drives'||/HALFTIME|END_PERIOD/.test(game.statusName||'')) return [];\n const offense=alias(game.teams.find(t=>t.id===game.possession)?.abbreviation);\n const opponents=game.teams.filter(t=>t.id!==game.possession).map(t=>alias(t.abbreviation));\n return roster.filter(p=>p.position==='D/ST'?opponents.includes(p.team):p.team===offense&&(p.position!=='K'||(game.down===4&&game.yardsToGoal!==null&&game.yardsToGoal<=35)));\n}\nexport function rankGames(games,roster){\n return games.filter(g=>g.state==='in'&&g.phase!=='between-drives'&&!/HALFTIME|END_PERIOD/.test(g.statusName||'')).map(g=>{\n  const players=involved(g,roster),distance=g.yardsToGoal;\n  return {game:g,players,score:(players.length?1000:0)+(distance===null?0:100-distance),urgent:players.length>0||distance!==null&&distance<=20};\n }).sort((a,b)=>b.score-a.score||a.game.id.localeCompare(b.game.id));\n}\nexport function chooseGame(games,roster,currentId,changedAt,now){\n const ranked=rankGames(games,roster),best=ranked[0];if(!best)return null;\n const current=ranked.find(x=>x.game.id===currentId);\n if(current&&best.game.id!==currentId&&best.score-current.score<12&&now-changedAt<6000)return current;\n return best;\n}\nexport function parseRoster(value){\n const lines=value.split('\\n').map(x=>x.trim()).filter(Boolean);\n if(lines.length>20)throw new Error('Use up to 20 starters.');\n return lines.map((line,index)=>{\n  const [name,rawTeam,rawPosition,...rest]=line.split(',').map(x=>x.trim());\n  const team=alias(rawTeam?.toUpperCase()),position=rawPosition?.toUpperCase();\n  if(!name||name.length>60||!TEAMS.includes(team)||!['QB','RB','WR','TE','K','D/ST'].includes(position)||rest.length)throw new Error(`Line ${index+1}: use name, NFL team, position.`);\n  return {name,team,position};\n });\n}\nexport function safeVideo(value){\n if(!value)return '';\n const u=new URL(value);\n if(u.protocol!=='https:'||u.username||u.password||!(/\\.(mp4|webm|m3u8)$/i.test(u.pathname)))throw new Error('Use a direct HTTPS .mp4, .webm or .m3u8 video URL.');\n return u.href;\n}\nexport function gameKey(game){return game.teams.map(t=>alias(t.abbreviation)).sort().join('-');}\nexport function simulation(seconds){\n const phase=Math.min(5,Math.floor(seconds/12));\n const spec=[['CHI','GB',21,24,'3','9'],['PHI','DAL',14,10,'21','6'],['IND','HOU',17,17,'11','34'],['SEA','SF',20,23,'26','25']];\n const games=spec.map(([a,b,sa,sb,aid,bid],i)=>({id:`test-${i}`,name:`${a} @ ${b}`,teams:[{id:aid,abbreviation:a,score:String(sa)},{id:bid,abbreviation:b,score:String(sb)}],state:'in',phase:'scrimmage',statusName:'STATUS_IN_PROGRESS',possession:bid,yardsToGoal:65+i*3,down:2,downDistance:'2nd & 6',period:4,clock:'4:18',detail:'4th · 4:18',redZone:false}));\n if(phase<3){games[phase].possession=games[phase].teams[0].id;games[phase].yardsToGoal=[34,18,8][phase];games[phase].redZone=phase>0;}\n if(phase===3){games[3].yardsToGoal=3;games[3].redZone=true;games[3].downDistance='2nd & goal';}\n if(phase===4){games.forEach(g=>{g.yardsToGoal=70;g.statusName='STATUS_HALFTIME';g.detail='Drive break';});}\n if(phase===5){games[0].possession='3';games[0].yardsToGoal=9;games[0].redZone=true;games[0].downDistance='1st & goal';}\n return games;\n}\n"},"/highlights.js":{"type":"text/javascript","body":"// Published ESPN clips and text play events stay distinct throughout the app.\nconst clean=s=>String(s || '').slice(0,1200);\nexport function mediaURL(value) {\n  try {\n    const u=new URL(value);\n    return u.protocol==='https:' && !u.username && !u.password && !u.port &&\n      (u.hostname==='espnmedia-cdn.akamaized.net' || u.hostname==='media.video-cdn.espn.com') &&\n      /\\.mp4$/i.test(u.pathname)?u.href:null;\n  } catch{return null;}\n}\nexport function playable(item,now=Date.now()) {\n  return !!mediaURL(item.mediaUrl) && (!item.embargoAt || item.embargoAt<=now) && (!item.expiresAt || item.expiresAt>now) && item.desktopAllowed!==false;\n}\nexport function espnURL(value) {\n  try {const u=new URL(value);return u.protocol==='https:' && !u.username && !u.password && (u.hostname==='espn.com' || u.hostname.endsWith('.espn.com'))?u.href:null;} catch {return null;}\n}\nconst norm=s=>String(s || '').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();\nexport function relevance(item,roster) {\n  const text=` ${norm(item.title+' '+item.description)} `;\n  const players=roster.filter(p=>item.athleteIds.includes(p.id) || (norm(p.name).split(' ').length>=2 && text.includes(` ${norm(p.name)} `)));\n  const team=roster.some(p=>item.teamIds.includes(p.teamId));\n  return {players:players.map(p=>p.name),tier:players.length?'player':team?'team':'league'};\n}\nexport function normalizeHighlights(raw,game,now=Date.now()) {\n  if (!raw || typeof raw!=='object' || (!Array.isArray(raw.videos) && !Array.isArray(raw.scoringPlays) && !Array.isArray(raw.plays) && !raw.header)) throw new Error('Unexpected game-summary format');\n  const items=[];\n  for(const v of raw.videos || []) {\n    const videoId=String(v.id || '');\n    const url=espnURL(v.links?.web?.href) || (/^\\d+$/.test(videoId)?espnURL(`https://www.espn.com/video/clip/_/id/${videoId}`):null);\n    if(!url)continue;\n    const tags=v.categories || [];\n    const mediaUrl=[v.links?.source?.href,v.links?.source?.SD?.href,v.links?.mobile?.source?.href,v.links?.source?.HD?.href].map(mediaURL).find(Boolean) || null;\n    const devices=v.deviceRestrictions,desktopAllowed=!devices || (devices.type==='whitelist'?Array.isArray(devices.devices)&&devices.devices.includes('desktop'):devices.type==='blacklist'?!devices.devices?.includes('desktop'):false);\n    items.push({id:`clip:${/^\\d+$/.test(videoId)?videoId:url}`,kind:'clip',gameId:game.id,gameName:game.name,title:clean(v.headline || v.title || 'ESPN game highlight'),description:clean(v.description),url,mediaUrl,desktopAllowed,\n      embargoAt:Date.parse(v.timeRestrictions?.embargoDate)||0,expiresAt:Date.parse(v.timeRestrictions?.expirationDate)||0,\n      athleteIds:tags.filter(t=>t.type==='athlete').map(t=>String(t.athlete?.id || t.athleteId || t.id || '')).filter(Boolean),\n      teamIds:tags.filter(t=>t.type==='team').map(t=>String(t.team?.id || t.teamId || t.id || '')).filter(Boolean),\n      publishedAt:Number.isFinite(Date.parse(v.originalPublishDate))?Date.parse(v.originalPublishDate):now,discoveredAt:now,duration:Number(v.duration)||0});\n  }\n  const plays=new Map();\n  const playURL=espnURL(raw.header?.links?.find(l=>l.rel?.includes('pbp'))?.href) || (/^\\d+$/.test(game.id)?`https://www.espn.com/nfl/playbyplay/_/gameId/${game.id}`:null);\n  for(const p of raw.scoringPlays || []) if(p.id) plays.set(String(p.id),{...p,scoringPlay:true});\n  const drivePlays=[...(raw.drives?.previous || []),raw.drives?.current].flatMap(d=>d?.plays || []);\n  for(const p of [...(raw.plays || []),...drivePlays]) if(p.id && (p.scoringPlay || p.isTurnover || /interception|fumble recovery/i.test(p.type?.text || '') || Number(p.statYardage)>=20)) plays.set(String(p.id),{...plays.get(String(p.id)),...p});\n  for(const [playId,p] of plays) items.push({id:`play:${game.id}:${playId}`,kind:'play',gameId:game.id,gameName:game.name,title:clean(p.type?.text || 'Scoring play'),description:clean(p.text),\n    athleteIds:[...(p.participants || []).map(x=>String(x.athlete?.id || '')),...(p.athletesInvolved || []).map(x=>String(x.id || ''))].filter(Boolean),teamIds:[p.team?.id,...(p.teamParticipants || []).map(t=>t.team?.id || t.id)].filter(Boolean).map(String),\n    url:playURL,publishedAt:Number.isFinite(Date.parse(p.wallclock))?Date.parse(p.wallclock):now,discoveredAt:now,duration:0,period:p.period?.number || 0,clock:p.clock?.displayValue || ''});\n  return items;\n}\nexport function mergeHighlights(previous,incoming,now=Date.now()) {\n  const map=new Map(previous.map(h=>[h.id,h]));\n  for(const h of incoming) {\n    const old=map.get(h.id);\n    map.set(h.id,{...h,publishedAt:old?.publishedAt || h.publishedAt,discoveredAt:old?.discoveredAt || h.discoveredAt,opened:!!old?.opened,played:!!old?.played,attemptedAt:old?.attemptedAt || 0,playbackError:old?.playbackError || ''});\n  }\n  return [...map.values()].filter(h=>now-h.discoveredAt<48*3600000).sort((a,b)=>b.discoveredAt-a.discoveredAt || a.id.localeCompare(b.id)).slice(0,160);\n}\nexport function highlightView(items,roster,delaySeconds,now=Date.now()) {\n  return items.filter(h=>h.discoveredAt<=now-delaySeconds*1000).map(h=>({...h,...relevance(h,roster)})).sort((a,b)=>({player:0,team:1,league:2}[a.tier]-{player:0,team:1,league:2}[b.tier]) || b.publishedAt-a.publishedAt);\n}\n"},"/":{"type":"text/html","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f6f6f3\"><meta name=\"description\" content=\"A simple, personal football viewing room.\"><title>Fantasy Director</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body>\n<header><a href=\"/\" class=\"brand\">Fantasy Director</a><div class=\"header-actions\"><button id=\"connectionButton\">Connect roster</button><button id=\"settingsButton\" aria-label=\"Open stream settings\">Settings</button></div></header>\n<main>\n<section class=\"connect-bar\" id=\"connectBar\"><form id=\"leagueForm\"><label for=\"leagueId\">Connect your ESPN roster</label><div class=\"inline\"><input id=\"leagueId\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Paste league ID\" required aria-describedby=\"importStatus\"><button type=\"submit\" id=\"importButton\" class=\"primary\">Import roster</button></div></form><p id=\"importStatus\" role=\"status\">Enter your league ID, then choose your team.</p><div id=\"teamPicker\" hidden><label for=\"teamSelect\">Your team</label><select id=\"teamSelect\"></select><button id=\"useTeam\" class=\"primary\">Use this team</button></div></section>\n<div class=\"toolbar\"><div class=\"mode-tabs\" aria-label=\"Viewing mode\"><button id=\"replayMode\" aria-pressed=\"true\">Replay test</button><button id=\"liveMode\" aria-pressed=\"false\">Live games</button></div><label class=\"auto-label\"><input type=\"checkbox\" id=\"autoDirector\" checked> Auto director</label></div>\n<div class=\"watch-layout\"><section class=\"watch-column\" aria-label=\"Watching\">\n<div class=\"player\" id=\"player\"><iframe id=\"gameFrame\" title=\"Full game replay\" allow=\"autoplay; fullscreen; picture-in-picture\" allowfullscreen sandbox=\"allow-scripts allow-same-origin allow-presentation\" referrerpolicy=\"no-referrer\" hidden></iframe><video id=\"gameVideo\" controls playsinline preload=\"none\" hidden></video><video id=\"clipVideo\" controls playsinline preload=\"none\" hidden></video><div class=\"player-empty\" id=\"playerEmpty\"><h1>Ready when you are.</h1><p>Choose a replay to test your viewing room.</p><button id=\"loadReplay\" class=\"primary\">Load replay</button></div><button id=\"playVideo\" class=\"play-overlay\" hidden>Play video</button></div>\n<div class=\"now\"><div><div id=\"modeCaption\" class=\"caption\">REPLAY TEST</div><h1 id=\"gameTitle\">Cowboys at Eagles</h1><p id=\"reason\">A.J. Brown’s offense has possession.</p></div><button id=\"returnLive\" hidden>Return to game</button></div>\n<div class=\"test-bar\" id=\"testBar\"><button id=\"startTest\" class=\"primary\">Start test</button><button id=\"nextTest\">Next switch →</button><button id=\"restartTest\" aria-label=\"Restart test\">Restart</button><span id=\"testStep\">1 of 5</span></div>\n<p class=\"player-note\" id=\"playerNote\">Real replays from <a href=\"https://nfl-video.com/full-game-replay\" target=\"_blank\" rel=\"noopener noreferrer\">NFL-Video ↗</a>. Switching events are simulated, not synchronized with the footage.</p>\n<a id=\"sourceLink\" class=\"source-link\" href=\"https://nfl-video.com/dallas-cowboys-vs-philadelphia-eagles-full-game-replay-nfl-week-07-october-26-2026\" target=\"_blank\" rel=\"noopener noreferrer\">Open original replay ↗</a><p id=\"playbackNote\" class=\"player-note\">Press play inside the embedded player if it doesn’t start. Each test cut loads the selected replay.</p>\n</section>\n<aside><div class=\"side-tabs\" role=\"tablist\" aria-label=\"Viewing details\"><button role=\"tab\" id=\"gamesTab\" aria-selected=\"true\" aria-controls=\"gamesPanel\">Games</button><button role=\"tab\" id=\"rosterTab\" aria-selected=\"false\" aria-controls=\"rosterPanel\">Roster</button><button role=\"tab\" id=\"clipsTab\" aria-selected=\"false\" aria-controls=\"clipsPanel\">Highlights</button></div>\n<section role=\"tabpanel\" id=\"gamesPanel\" aria-labelledby=\"gamesTab\"><div class=\"panel-heading\"><h2 id=\"gamesHeading\">Test games</h2><span id=\"feedStatus\">Week 7 replays</span></div><div id=\"gameList\"></div><p class=\"small-note\" id=\"gamesNote\">Choose a game to pin it. Turn Auto director on to resume switching.</p></section>\n<section role=\"tabpanel\" id=\"rosterPanel\" aria-labelledby=\"rosterTab\" hidden><div class=\"panel-heading\"><h2 id=\"teamName\">Sample roster</h2><button id=\"refreshRoster\" hidden>Refresh</button></div><p class=\"small-note\" id=\"rosterNote\">Import your team above to replace these players.</p><div id=\"rosterList\"></div></section>\n<section role=\"tabpanel\" id=\"clipsPanel\" aria-labelledby=\"clipsTab\" hidden><div class=\"panel-heading\"><h2>Highlights</h2></div><label class=\"auto-label\"><input type=\"checkbox\" id=\"autoClips\" checked> Play during quiet moments</label><div id=\"clipList\"></div><p class=\"small-note\">Priority game action interrupts automatic highlights.</p></section></aside></div>\n<p id=\"notice\" role=\"status\" hidden></p></main>\n<dialog id=\"settingsDialog\"><form id=\"settingsForm\"><div class=\"dialog-top\"><h2>Stream settings</h2><button type=\"button\" id=\"closeSettings\" aria-label=\"Close settings\">✕</button></div><p>Replay test already has two games connected. For Live games, add a direct MP4, WebM, or browser-supported HLS URL below.</p><div id=\"streamInputs\"></div><details><summary>Edit roster manually</summary><p>One starter per line: name, team, position.</p><textarea id=\"manualRoster\" rows=\"5\" aria-label=\"Manual roster\"></textarea></details><p id=\"settingsError\" role=\"alert\"></p><button class=\"primary\" type=\"submit\">Save settings</button></form></dialog><script type=\"module\" src=\"/app.js\"></script></body></html>\n"},"/replays.js":{"type":"text/javascript","body":"export const SOURCES=[{id:'replay-phi',name:'Cowboys at Eagles',short:'DAL @ PHI',teams:[{id:'6',abbreviation:'DAL',score:''},{id:'21',abbreviation:'PHI',score:''}],embed:'https://ok.ru/videoembed/16641575946924',page:'https://nfl-video.com/dallas-cowboys-vs-philadelphia-eagles-full-game-replay-nfl-week-07-october-26-2026'},{id:'replay-ind',name:'Colts at Vikings',short:'IND @ MIN',teams:[{id:'11',abbreviation:'IND',score:''},{id:'16',abbreviation:'MIN',score:''}],embed:'https://ok.ru/videoembed/15876147841708',page:'https://nfl-video.com/indianapolis-colts-vs-minnesota-vikings-full-game-replay-nfl-week-07-october-25-2026'}];\nexport function scenarios(step){const g=SOURCES.map(s=>({...s,teams:s.teams.map(t=>({...t})),state:'in',statusName:'STATUS_IN_PROGRESS',phase:'scrimmage',possession:s.teams[1].id,yardsToGoal:70,down:2,downDistance:'2nd & 6',detail:'Scripted test event',redZone:false}));\n if(step===0){g[0].possession='21';g[0].yardsToGoal=42;}\n if(step===1){g[0].possession='6';g[1].possession='11';g[1].yardsToGoal=18;g[1].redZone=true;}\n if(step===2){g[0].possession='6';g[0].yardsToGoal=6;g[0].redZone=true;}\n if(step===3){for(const x of g){x.statusName='STATUS_HALFTIME';x.detail='Quiet moment';}}\n if(step===4){g[0].possession='6';g[1].possession='11';g[1].yardsToGoal=5;g[1].redZone=true;}\n return g;}\n"},"/style.css":{"type":"text/css","body":":root{font-family:Arial,Helvetica,sans-serif;color:#202323;background:#f6f6f3;font-synthesis:none;--muted:#616963;--line:#d9ddd6;--green:#215a3f;--soft:#e9efe8}*{box-sizing:border-box}body{margin:0;font-size:16px;line-height:1.5}button,input,select,textarea{font:inherit}button{background:white;color:#282e29;border:1px solid #cdd4cb;padding:10px 16px;border-radius:7px;cursor:pointer;font-weight:500}button:hover{background:#edf1eb}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #588765;outline-offset:3px}.primary{background:var(--green);color:white;border-color:var(--green)}.primary:hover{background:#17482f}a{color:inherit;text-underline-offset:4px}[hidden]{display:none!important}header{max-width:1320px;margin:auto;padding:27px 40px;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line)}.brand{font-size:22px;font-weight:700;letter-spacing:-.6px;text-decoration:none}.header-actions{display:flex;gap:10px}.header-actions button{font-size:14px}main{max-width:1320px;margin:0 auto;padding:28px 40px 50px}.connect-bar{background:white;border:1px solid var(--line);border-radius:10px;padding:20px 24px;margin-bottom:28px}.connect-bar form{display:flex;align-items:center;justify-content:space-between;gap:24px}.connect-bar label{font-weight:600}.inline{display:flex;gap:10px}input:not([type=checkbox]),select,textarea{background:white;border:1px solid #b8c2b5;border-radius:6px;padding:10px 13px;min-width:0;color:#222}#leagueId{width:230px}.connect-bar p{color:var(--muted);font-size:14px;margin:10px 0 0}.connect-bar #teamPicker{display:flex;gap:12px;align-items:center;margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}#teamSelect{flex:1;max-width:450px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:20px}.mode-tabs{display:flex;gap:5px;border:1px solid var(--line);background:#e9ece6;padding:4px;border-radius:9px}.mode-tabs button{border:0;background:none;padding:9px 20px;color:#596157}.mode-tabs button[aria-pressed=true]{background:white;color:#202b21;box-shadow:0 1px 3px #16281116}.auto-label{display:flex;gap:9px;align-items:center;font-size:14px;cursor:pointer}.auto-label input{accent-color:var(--green);width:17px;height:17px;margin:0}.watch-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:30px}.player{aspect-ratio:16/9;position:relative;background:#111613;border-radius:10px;overflow:hidden}.player iframe,.player video{border:0;position:absolute;inset:0;width:100%;height:100%;background:#0c0f0d;object-fit:contain}.player-empty{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;color:white;padding:28px}.player-empty h1{font-size:26px;margin:0 0 5px}.player-empty p{font-size:16px;color:#aeb9b0;margin:0 0 23px}.player-empty .primary{background:#e5eee3;color:#203c29;border-color:transparent}.play-overlay{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:white;box-shadow:0 4px 30px #0005}.now{display:flex;justify-content:space-between;align-items:center;margin:22px 0;gap:20px}.caption{font-size:12px;font-weight:600;color:var(--green);letter-spacing:1px}.now h1{font-size:28px;line-height:1.2;letter-spacing:-.6px;margin:6px 0 8px;font-weight:600}.now p{font-size:16px;color:#535d54;margin:0}.test-bar{display:flex;align-items:center;gap:10px;border-top:1px solid var(--line);padding-top:18px}.test-bar button{font-size:14px}.test-bar>span{font-size:14px;color:var(--muted);margin-left:auto}.player-note{font-size:13px;line-height:1.6;color:var(--muted);margin:17px 0 9px;max-width:700px}.source-link{font-size:14px;color:var(--green)}#playbackNote{margin-top:7px}aside{border:1px solid var(--line);border-radius:10px;background:white;align-self:start;overflow:hidden}.side-tabs{display:grid;grid-template-columns:1fr 1fr 1fr;border-bottom:1px solid var(--line);padding:0 12px}.side-tabs button{border:0;border-radius:0;background:none;font-size:14px;padding:16px 6px;border-bottom:3px solid transparent}.side-tabs button[aria-selected=true]{border-bottom-color:var(--green);color:var(--green);font-weight:700}aside section{padding:18px}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:18px}.panel-heading h2{font-size:17px;line-height:1.4;font-weight:600;margin:0}.panel-heading span{font-size:12px;color:var(--muted)}.panel-heading button{font-size:13px;padding:6px 10px}.game{display:block;width:100%;text-align:left;padding:16px;margin-bottom:12px;border-color:#dde2d9}.game[aria-pressed=true]{border-color:#52785b;box-shadow:inset 3px 0 var(--green);background:#f0f5ee}.game strong{font-size:17px;display:block;font-weight:600}.game .game-meta{font-size:13px;color:var(--muted);display:block;margin-top:5px}.game .game-state{display:block;font-size:12px;margin-top:9px;color:var(--green)}.small-note{font-size:13px;color:var(--muted);line-height:1.6;margin:16px 0 0}.roster-item{display:flex;align-items:center;gap:12px;border-bottom:1px solid #e9ece6;padding:13px 0}.roster-item:last-child{border:0}.position{font-size:12px;color:#526550;background:#edf1e9;border-radius:4px;min-width:36px;text-align:center;padding:4px}.roster-item strong{font-size:15px;font-weight:500}.roster-item small{display:block;font-size:12px;color:var(--muted)}.roster-item.active strong{color:var(--green);font-weight:700}.clip{padding:17px 0;border-bottom:1px solid var(--line)}.clip button{font-size:14px;display:block;width:100%;text-align:left;line-height:1.5;padding:12px}.clip a{font-size:12px;display:inline-block;margin-top:8px;color:var(--muted)}.empty-list{color:var(--muted);font-size:14px;line-height:1.6;padding:10px 0}dialog{background:#fff;color:#242b24;border:1px solid var(--line);border-radius:12px;width:560px;max-width:calc(100% - 24px);max-height:90vh;padding:28px}dialog::backdrop{background:#10201666}.dialog-top{display:flex;align-items:center;justify-content:space-between}.dialog-top h2{font-size:24px;margin:0}.dialog-top button{border:0;font-size:20px;padding:0 5px}dialog p{color:var(--muted);font-size:14px}.stream-row{margin:18px 0}.stream-row label{display:block;font-size:14px;font-weight:600;margin-bottom:7px}.stream-row input{width:100%}details{border-top:1px solid var(--line);margin:24px 0;padding-top:18px}summary{cursor:pointer;font-size:15px}textarea{width:100%;font-size:14px;resize:vertical}#settingsError{color:#a12b22}#notice{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:#233b2a;color:white;border-radius:8px;padding:13px 22px;box-shadow:0 5px 25px #0002;max-width:90%;z-index:10;font-size:14px}#returnLive{font-size:14px;white-space:nowrap}@media(min-width:1550px){main,header{max-width:1450px}.watch-layout{grid-template-columns:minmax(0,1fr) 330px}}@media(max-width:1000px){main,header{padding-left:24px;padding-right:24px}.watch-layout{gap:20px;grid-template-columns:minmax(0,1fr) 280px}.connect-bar form{align-items:flex-start;flex-direction:column;gap:12px}.now h1{font-size:24px}.now p{font-size:15px}.now{align-items:flex-start;flex-direction:column;gap:10px}.test-bar{gap:7px;flex-wrap:wrap}.test-bar button{padding:8px 11px}.connect-bar{padding:18px 20px}.brand{font-size:20px}}@media(max-width:760px){header{padding:20px}.header-actions button{padding:8px 10px;font-size:13px}.brand{font-size:18px}main{padding:20px}.watch-layout{grid-template-columns:1fr}.toolbar{gap:10px}.mode-tabs button{padding:8px 12px;font-size:14px}.auto-label{font-size:13px}.inline{width:100%}#leagueId{width:100%;flex:1}.inline button{white-space:nowrap;font-size:14px}.connect-bar form{gap:14px}.connect-bar label{font-size:16px}.connect-bar #teamPicker{flex-wrap:wrap}#teamPicker select{width:100%;flex:auto}.connect-bar{margin-bottom:20px}.now{margin:18px 0}.now h1{font-size:25px}.side-tabs button{font-size:15px}.player-empty h1{font-size:21px}.player-empty p{font-size:14px}.player-empty button{font-size:14px}aside{margin-top:5px}.player-note{font-size:13px}.test-bar button{font-size:13px}.test-bar>span{font-size:12px}.header-actions{gap:5px}#connectionButton{max-width:155px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"}};
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==="/api/league")return leagueAPI(request,env);if(request.method!=="GET"&&request.method!=="HEAD")return new Response("Method not allowed",{status:405});const file=assets[url.pathname];if(!file)return new Response("Not found",{status:404});return new Response(request.method==="HEAD"?null:file.body,{headers:{"Content-Type":file.type+"; charset=utf-8","Cache-Control":"no-cache","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer"}})}};